<script setup lang="ts">
import { useForm,Link } from '@inertiajs/vue3'; import { ref } from 'vue'; import AdminLayout from '@/Layouts/AdminLayout.vue'; import PageMeta from '@/Components/PageMeta.vue'; import type { Doctor,Patient,PdfTemplate } from '@/types';
type EnumOption=string|{name?:string;value?:string}; const props=defineProps<{types:EnumOption[];doctors:Doctor[];patients:Patient[];templates:PdfTemplate[]}>(); const selected=ref<File|null>(null); const form=useForm<{type:string;doctor_id:string;patient_id:string;pdf_template_id:string;document:File|null}>({type:'',doctor_id:'',patient_id:'',pdf_template_id:'',document:null}); const val=(o:EnumOption)=>typeof o==='string'?o:o.value||o.name||''; const labels:Record<string,string>={MEDICAL_CERTIFICATE:'Certificado médico',MEDICAL_REPORT:'Informe médico',PRESCRIPTION:'Receta médica',LAB_RESULT:'Resultado de laboratorio',REFERRAL:'Referencia médica',OTHER:'Otro'}; const choose=(e:Event)=>{selected.value=(e.target as HTMLInputElement).files?.[0]||null;form.document=selected.value}; const submit=()=>form.post(route('admin.documents.store'),{forceFormData:true,preserveScroll:true});
</script>
<template><AdminLayout title="Cargar documento" eyebrow="Documentos / Nuevo"><PageMeta title="Cargar documento" noindex /><section class="admin-content narrow-content"><div class="step-line"><span class="active">1 <b>Carga</b></span><i></i><span>2 <b>Procesamiento</b></span><i></i><span>3 <b>Revisión</b></span><i></i><span>4 <b>Emisión</b></span></div><form class="panel form-panel" @submit.prevent="submit"><div class="panel-head"><div><p class="kicker">Nuevo registro</p><h2>Documento médico en PDF</h2><p>El sistema conservará el original y calculará su huella digital.</p></div></div><label class="upload-zone upload-zone--admin" for="document"><span>PDF</span><strong>{{ selected?.name||'Arrastre o seleccione un archivo PDF' }}</strong><small v-if="selected">{{ (selected.size/1024/1024).toFixed(2) }} MB</small><small v-else>Solo documentos PDF válidos. El límite depende de la configuración del sistema.</small><input id="document" type="file" accept="application/pdf,.pdf" required @change="choose"></label><span v-if="form.errors.document" class="field-error">{{ form.errors.document }}</span><div class="form-grid"><div class="field"><label for="type">Tipo de documento</label><select id="type" v-model="form.type" required><option value="" disabled>Seleccione un tipo</option><option v-for="option in props.types" :key="val(option)" :value="val(option)">{{ labels[val(option)]||val(option) }}</option></select><span v-if="form.errors.type" class="field-error">{{ form.errors.type }}</span></div><div class="field"><label for="template">Plantilla <i>opcional</i></label><select id="template" v-model="form.pdf_template_id"><option value="">Detección automática / sin plantilla</option><option v-for="item in templates" :key="item.id" :value="item.id">{{ item.name }}</option></select><span v-if="form.errors.pdf_template_id" class="field-error">{{ form.errors.pdf_template_id }}</span></div><div class="field"><label for="patient">Paciente <i>opcional</i></label><select id="patient" v-model="form.patient_id"><option value="">Asignar durante la revisión</option><option v-for="item in patients" :key="item.id" :value="item.id">{{ item.last_name }}, {{ item.first_name }}</option></select><span v-if="form.errors.patient_id" class="field-error">{{ form.errors.patient_id }}</span></div><div class="field"><label for="doctor">Profesional <i>opcional</i></label><select id="doctor" v-model="form.doctor_id"><option value="">Asignar durante la revisión</option><option v-for="item in doctors" :key="item.id" :value="item.id">{{ item.last_name }}, {{ item.first_name }}</option></select><span v-if="form.errors.doctor_id" class="field-error">{{ form.errors.doctor_id }}</span></div></div><div class="form-actions"><Link href="/admin/documents">Cancelar</Link><button class="button button--admin" :disabled="form.processing||!selected">{{ form.processing?'Cargando…':'Cargar y procesar →' }}</button></div><progress v-if="form.progress" :value="form.progress.percentage" max="100">{{ form.progress.percentage }}%</progress></form></section></AdminLayout></template>
